from fastapi.params import Depends, Security
from typing import Callable

def test_depends_hashable():
    d1 = Depends(dependency=lambda: 1)
    d2 = Depends(dependency=lambda: 1)
    # Note: lambdas are not equal but the instance of Depends should be hashable
    # The issue is not about value equality of dependencies (which are callables)
    # but about whether the Depends object itself can be hashed.
    try:
        hash(d1)
        print("Depends is hashable")
    except TypeError as e:
        print(f"Depends is NOT hashable: {e}")

def test_security_hashable():
    s1 = Security(scopes=["admin", "user"])
    try:
        hash(s1)
        print("Security with list scopes is hashable")
    except TypeError as e:
        print(f"Security with list scopes is NOT hashable: {e}")

if __name__ == "__main__":
    test_depends_hashable()
    test_security_hashable()

